/** Circular credential seal, echoing the stamp in the reference hero. */
export function Seal({ className = "" }: { className?: string }) {
  const label =
    "MAGNA CUM LAUDE • B.SC. COMPUTER SCIENCE & STATISTICS • BINA NUSANTARA • ";

  return (
    <svg viewBox="0 0 200 200" className={className} role="img" aria-label={label}>
      <defs>
        <path
          id="seal-arc"
          d="M100,100 m-74,0 a74,74 0 1,1 148,0 a74,74 0 1,1 -148,0"
        />
      </defs>
      <circle cx="100" cy="100" r="97" fill="var(--color-paper)" />
      <circle
        cx="100"
        cy="100"
        r="96"
        fill="none"
        stroke="var(--color-ink)"
        strokeWidth="1.5"
      />
      <circle
        cx="100"
        cy="100"
        r="60"
        fill="none"
        stroke="var(--color-line)"
        strokeWidth="1"
      />
      <text
        fontSize="11.2"
        letterSpacing="1.6"
        fill="var(--color-ink)"
        fontWeight="600"
      >
        <textPath href="#seal-arc" startOffset="0%">
          {label}
        </textPath>
      </text>
      {/* Simple layered-data mark in the middle */}
      <g stroke="var(--color-teal)" strokeWidth="4.5" strokeLinecap="round" fill="none">
        <ellipse cx="100" cy="82" rx="26" ry="10" />
        <path d="M74 82v18c0 5.5 11.6 10 26 10s26-4.5 26-10V82" />
        <path d="M74 104v14c0 5.5 11.6 10 26 10s26-4.5 26-10v-14" />
      </g>
      <circle cx="100" cy="136" r="3.5" fill="var(--color-coral)" />
    </svg>
  );
}

